import { useEffect, useState } from 'react'
import { HomePage } from './pages/HomePage'
import { StorePage } from './pages/StorePage'
import { ShopLaptopsPage } from './pages/ShopLaptopsPage'
import { ShopTabletsPage } from './pages/ShopTabletsPage'

export function App() {
  const [currentPath, setCurrentPath] = useState(window.location.pathname)

  useEffect(() => {
    const handlePopState = () => setCurrentPath(window.location.pathname)
    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [])

  const path = currentPath.toLowerCase()

  if (path.includes('store.html')) {
    return <StorePage />
  }
  if (path.includes('shop-laptops.html')) {
    return <ShopLaptopsPage />
  }
  if (path.includes('shop-tablets.html')) {
    return <ShopTabletsPage />
  }

  // Default to HomePage for index.html or root
  return <HomePage />
}
EOF

